/** A member entry with sub-resource accessor methods. Response data properties are deeply readonly. */
export type HydratedMember<T> = DeepReadonly<T> & MemberSubResources;

// ---------------------------------------------------------------------------
// MembersResource
// ---------------------------------------------------------------------------

/** @internal Attach sub-resource accessors to a member entry. */
function _hydrateMember<T extends object>(
  entry: T,
  resource: MembersResource,
): HydratedMember<T> {
  return Object.assign(entry, {
    accessibleInodes: {
      list: (query?: ListAccessibleInodesQuery) =>
        resource.listAccessibleInodes((entry as any).memberId, query),
      listAll: (query?: ListAccessibleInodesQuery) =>
        resource.listAccessibleInodesAll((entry as any).memberId, query),
    },
    favoriteInodes: {
      list: (query?: ListFavoriteInodesQuery) =>
        resource.listFavoriteInodes((entry as any).memberId, query),
      listAll: (query?: ListFavoriteInodesQuery) =>
        resource.listFavoriteInodesAll((entry as any).memberId, query),
    },
    recentInodes: {
      list: (query?: ListRecentInodesQuery) =>
        resource.listRecentInodes((entry as any).memberId, query),
      listAll: (query?: ListRecentInodesQuery) =>
        resource.listRecentInodesAll((entry as any).memberId, query),
    },
    schedules: {
      list: (query?: ListMemberSchedulesQuery) =>
        resource.listSchedules((entry as any).memberId, query),
      listAll: (query?: ListMemberSchedulesQuery) =>
        resource.listSchedulesAll((entry as any).memberId, query),
    },
    teams: {
      list: (query?: ListMemberTeamsQuery) =>
        resource.listTeams((entry as any).memberId, query),
      listAll: (query?: ListMemberTeamsQuery) =>
        resource.listTeamsAll((entry as any).memberId, query),
    },
  }) as HydratedMember<T>;
}

