  /**
   * List members (Paginated)
   *
   * Source docs: https://help.sigmacomputing.com/reference/v2_1_listmembers
   *
   *
   * **Attention:** This API endpoint uses pagination by default.
   *
   * List all users in Sigma.
   *
   * ### Usage notes
   * - Filter your results using the `email` query parameter.
   * - Using `email` and `search` together is not supported.
   *
   * @param query - Query parameters
   * @returns ListMembersResponse
   */
  async list(
    query?: ListMembersQuery,
  ): Promise<HydratePage<ListMembersResponse, MemberSubResources>> {
    const { data, error, response } = await this.client.GET('/v2.1/members', {
      params: { query },
    });
    if (error) throw new SigmaApiError(error, response);
    const result = data! as any;
    if (Array.isArray(result)) {
      return result.map((e: any) => _hydrateMember(e, this)) as any;
    }
    if (result.entries && Array.isArray(result.entries)) {
      result.entries = result.entries.map((e: any) => _hydrateMember(e, this));
    }
    return result;
  }

